function startWaitlistOtpCooldown() {
  WAITLIST_OTP_COOLDOWN = 30;
  refreshWaitlistOtpButton();
  if (WAITLIST_OTP_TIMER) clearInterval(WAITLIST_OTP_TIMER);
  WAITLIST_OTP_TIMER = setInterval(function() {
